const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Dallasport, Washington coordinates (approximate center)
  const geometry = ee.Geometry.Point(-121.056, 45.698);
  const startDate = '2022-07-01';
  const endDate = '2022-07-31';
  const tempThresholdFahrenheit = 95; // Target temperature

  // 2. Data Acquisition & Check
  // Using ERA5-Land Hourly data for 2m air temperature
  let era5Collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(geometry)
    .select('temperature_2m'); // Temperature is in Kelvin

  const collectionSize = await era5Collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("Initial ERA5-Land images found: 0.");
    console.log("C1: Empty Collection (No ERA5-Land hourly data found for Dallasport, Washington in July 2022).");
    return;
  }
  console.log(`Initial ERA5-Land images found: ${collectionSize}.`);

  // Function to convert Kelvin to Fahrenheit
  const kelvinToFahrenheit = (image) => {
    return image.expression(
      '(K - 273.15) * 9/5 + 32',
      { 'K': image.select('temperature_2m') }
    ).rename('temperature_fahrenheit')
    .copyProperties(image, ['system:time_start']); // Keep time property for reference
  };

  // Apply the conversion to the collection
  const era5Fahrenheit = era5Collection.map(kelvinToFahrenheit);

  // Get the maximum temperature from the collection over the period
  const maxTempImage = era5Fahrenheit.qualityMosaic('temperature_fahrenheit');

  // Reduce the maximum temperature image to get a single value for the point
  // Use a scale appropriate for ERA5-Land (approx. 9-10 km)
  const maxTempResult = await maxTempImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: geometry,
    scale: 10000, // 10 km scale
    maxPixels: 1e9
  }).getInfo();

  const maxTempFahrenheit = maxTempResult ? maxTempResult['temperature_fahrenheit'] : null;

  // 3. Processing & Validation
  if (maxTempFahrenheit === null || maxTempFahrenheit === undefined || isNaN(maxTempFahrenheit)) {
    console.log("C3: Calculation Failure (Could not retrieve maximum temperature value).");
    return;
  }

  // 4. Final Answer
  const reachedThreshold = maxTempFahrenheit >= tempThresholdFahrenheit;

  console.log(`Max recorded temperature in July 2022 for Dallasport, WA: ${maxTempFahrenheit.toFixed(2)} °F.`);
  console.log(`Threshold: ${tempThresholdFahrenheit} °F.`);

  if (reachedThreshold) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
